transpose_conv_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void transpose_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* output,
    int B, int C_in, int H_in, int W_in,
    int O_C, int O_H, int O_W,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * O_C * O_H * O_W) return;

    // Decode global index into (batch, output_channel, out_height, out_width)
    int b = idx / (O_C * O_H * O_W);
    int rem = idx % (O_C * O_H * O_W);
    int oc = rem / (O_H * O_W);
    int rem2 = rem % (O_H * O_W);
    int oh_out = rem2 / O_W;
    int ow_out = rem2 % O_W;

    float sum = 0.0f;
    for (int c = 0; c < C_in; ++c) {
        // Input patch coordinates (transposed conv uses stride and dilation)
        int ih_in = oh_out * stride_h + padding_h - dilation_h * (oh_out > 0 ? (oh_out - 1) : 0);
        int iw_in = ow_out * stride_w + padding_w - dilation_w * (ow_out > 0 ? (ow_out - 1) : 0);

        if (ih_in >= 0 && ih_in < H_in && iw_in >= 0 && iw_in < W_in) {
            // Index into input tensor: [B, C_in, H_in, W_in]
            int in_idx = ((b * C_in + c) * H_in * W_in + ih_in) * W_in + iw_in;
            float val = input[in_idx];

            // Weight index: (oc, oh_out, ow_out, c)
            int w_idx = ((oc * O_H + oh_out) * W_in + iw_in) * C_in + c;  // placeholder
            float wval = weight[w_idx];
            sum += val * wval;
        }
    }
    output[idx] = sum;
}
"""

