conv_transpose2d_cuda_source = """
torch::Tensor conv_transpose2d_cuda(torch::Tensor x) {
    // Input: x [B, C_in, H_in, W_in]
    int B = x.size(0);
    int C_in = x.size(1);
    int H_in = x.size(2);
    int W_in = x.size(3);

    // Output dimensions (naive)
    int out_h = (H_in * stride_h + 2*padding_h - kernel_size[0]) / dilation_h + 1;
    int out_w = (W_in * stride_w + 2*padding_w - kernel_size[1]) / dilation_w + 1;

    // Allocate output tensor
    float* out_ptr = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks_h = (out_h + block_size - 1) / block_size;
    const int num_blocks_w = (out_w + block_size - 1) / block_size;

    // Launch kernel: we need O_C, but for this stub we assume O_C = 64.
    const int O_C = 64;   // placeholder
    int total_elements = B * O_C * out_h * out_w;
    int threads_per_block = block_size;
    int num_blocks = (total_elements + threads_per_block - 1) / threads_per_block;

    transpose_conv2d_kernel<<<num_blocks, threads_per_block>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),   // placeholder: we need the correct weight tensor
        out_ptr,
        B, C_in, H_in, W_in,
        O_C, out_h, out_w,
