        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.bias = bias

        # Register the custom conv_transpose2d_cuda function (already loaded)
        self.conv_transpose2d_cuda = conv_transpose2d_cuda  # type: ignore

    def forward(self, x):
        return self.conv_transpose2d_cuda(x)
